from collections import deque
class Solution:
    def shortestPath(self, grid, k):
        m, n = len(grid), len(grid[0])
        best = [[-1] * n for _ in range(m)]
        q = deque([(0, 0, k, 0)])
        best[0][0] = k
        while q:
            x, y, r, d = q.popleft()
            if x == m - 1 and y == n - 1:
                return d
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = x + dx, y + dy
                if 0 <= a < m and 0 <= b < n:
                    nr = r - grid[a][b]
                    if nr > best[a][b]:
                        best[a][b] = nr
                        q.append((a, b, nr, d + 1))
        return -1

