import bisect
class Solution:
    def medianSlidingWindow(self, nums, k):
        w = sorted(nums[:k])
        out = []
        for i in range(k, len(nums) + 1):
            out.append(float(w[k // 2]) if k % 2 else (w[k // 2 - 1] + w[k // 2]) / 2)
            if i == len(nums):
                break
            w.pop(bisect.bisect_left(w, nums[i - k]))
            bisect.insort(w, nums[i])
        return out
